    81	GF_Err ac3dmx_configure_pid(GF_Filter *filter, GF_FilterPid *pid, Bool is_remove)
    82	{
    83		const GF_PropertyValue *p;
    84		GF_AC3DmxCtx *ctx = gf_filter_get_udta(filter);
    85	
    86		if (is_remove) {
    87			ctx->ipid = NULL;
    88			if (ctx->opid) {
    89				gf_filter_pid_remove(ctx->opid);
    90				ctx->opid = NULL;
    91			}
    92			return GF_OK;
    93		}
    94		if (! gf_filter_pid_check_caps(pid))
    95			return GF_NOT_SUPPORTED;
    96	
    97		ctx->ipid = pid;
    98		p = gf_filter_pid_get_property(pid, GF_PROP_PID_TIMESCALE);
    99		if (p) ctx->timescale = p->value.uint;
   100	
   101		ctx->ac3_parser_bs = gf_ac3_parser_bs;
   102	
   103		p = gf_filter_pid_get_property(pid, GF_PROP_PID_CODECID);
   104		if (p && p->value.uint==GF_CODECID_EAC3) ctx->is_eac3 = GF_TRUE;
   105		else {
   106			p = gf_filter_pid_get_property(pid, GF_PROP_PID_MIME);
   107			if (p && p->value.string && strstr(p->value.string, "eac3")) ctx->is_eac3 = GF_TRUE;
   108			else {
   109				p = gf_filter_pid_get_property(pid, GF_PROP_PID_FILE_EXT);
   110				if (p && p->value.string && (strstr(p->value.string, "eac3")||strstr(p->value.string, "ec3"))) ctx->is_eac3 = GF_TRUE;
   111			}
   112		}
   113		if (ctx->is_eac3) {
   114			ctx->ac3_parser_bs = gf_eac3_parser_bs;
   115		}
   116	
   117		if (ctx->timescale && !ctx->opid) {
   118			ctx->opid = gf_filter_pid_new(filter);
   119			gf_filter_pid_copy_properties(ctx->opid, ctx->ipid);
   120			gf_filter_pid_set_property(ctx->opid, GF_PROP_PID_UNFRAMED, NULL);
   121	
   122			//make sure we move to audio (may happen if source filter is writegen)
   123			p = gf_filter_pid_get_property(ctx->ipid, GF_PROP_PID_STREAM_TYPE);
   124			if (!p || (p->value.uint==GF_STREAM_FILE)) {
   125				gf_filter_pid_set_property(ctx->opid, GF_PROP_PID_STREAM_TYPE, &PROP_UINT(GF_STREAM_AUDIO));
   126			}
   127		}
   128		if (ctx->timescale) ctx->copy_props = GF_TRUE;
   129		return GF_OK;
   130	}
   131	
   132	static void ac3dmx_check_dur(GF_Filter *filter, GF_AC3DmxCtx *ctx)
   133	{
   134		FILE *stream;
   135		GF_BitStream *bs;
   136		GF_AC3Config hdr;
   137		u64 duration, cur_dur, rate;
   138		s32 sr = -1;
   139		const GF_PropertyValue *p;
   140		if (!ctx->opid || ctx->timescale || ctx->file_loaded) return;
   141	
   142		if (ctx->index<=0) {
   143			ctx->file_loaded = GF_TRUE;
   144			return;
   145		}
   146	
   147		p = gf_filter_pid_get_property(ctx->ipid, GF_PROP_PID_FILEPATH);
   148		if (!p || !p->value.string || !strncmp(p->value.string, "gmem://", 7)) {
   149			ctx->is_file = GF_FALSE;
   150			ctx->file_loaded = GF_TRUE;
   151			return;
   152		}
   153		ctx->is_file = GF_TRUE;
   154	
   155		stream = gf_fopen_ex(p->value.string, NULL, "rb", GF_TRUE);
   156		if (!stream) {
   157			if (gf_fileio_is_main_thread(p->value.string))
   158				ctx->file_loaded = GF_TRUE;
   159			return;
   160		}
   161	
   162		ctx->index_size = 0;
   163	
   164		bs = gf_bs_from_file(stream, GF_BITSTREAM_READ);
   165		duration = 0;
   166		cur_dur = 0;
   167		while (	ctx->ac3_parser_bs(bs, &hdr, GF_FALSE) ) {
   168			if ((sr>=0) && (sr != hdr.sample_rate)) {
   169				duration *= hdr.sample_rate;
   170				duration /= sr;
   171	
   172				cur_dur *= hdr.sample_rate;
   173				cur_dur /= sr;
   174			}
   175			sr = hdr.sample_rate;
   176			duration += AC3_FRAME_SIZE;
   177			cur_dur += AC3_FRAME_SIZE;
   178			if (cur_dur > ctx->index * sr) {
   179				if (!ctx->index_alloc_size) ctx->index_alloc_size = 10;
   180				else if (ctx->index_alloc_size == ctx->index_size) ctx->index_alloc_size *= 2;
   181				ctx->indexes = gf_realloc(ctx->indexes, sizeof(AC3Idx)*ctx->index_alloc_size);
   182				ctx->indexes[ctx->index_size].pos = gf_bs_get_position(bs);
   183				ctx->indexes[ctx->index_size].duration = (Double) duration;
   184				ctx->indexes[ctx->index_size].duration /= sr;
   185				ctx->index_size ++;
   186				cur_dur = 0;
   187			}
   188	
   189			gf_bs_skip_bytes(bs, hdr.framesize);
   190		}
   191		rate = gf_bs_get_position(bs);
   192		gf_bs_del(bs);
   193		gf_fclose(stream);
   194	
   195		if (!ctx->duration.num || (ctx->duration.num  * sr != duration * ctx->duration.den)) {
   196			ctx->duration.num = (s32) duration;
   197			ctx->duration.den = sr;
   198	
   199			gf_filter_pid_set_property(ctx->opid, GF_PROP_PID_DURATION, & PROP_FRAC64(ctx->duration));
   200	
   201			if (duration && !gf_sys_is_test_mode() ) {
   202				rate *= 8 * ctx->duration.den;
   203				rate /= ctx->duration.num;
   204				ctx->bitrate = (u32) rate;
   205			}
   206		}
   207	
   208		p = gf_filter_pid_get_property(ctx->ipid, GF_PROP_PID_FILE_CACHED);
   209		if (p && p->value.boolean) ctx->file_loaded = GF_TRUE;
   210	}
   211	
   212	static void ac3dmx_check_pid(GF_Filter *filter, GF_AC3DmxCtx *ctx)
   213	{
   214		u8 *data;
   215		u32 size;
   216		if (!ctx->opid) {
   217			ctx->opid = gf_filter_pid_new(filter);
   218			ac3dmx_check_dur(filter, ctx);
   219		}
   220		if ((ctx->sample_rate == ctx->hdr.sample_rate) && (ctx->nb_ch == ctx->hdr.streams[0].channels) && !ctx->copy_props) return;
   221	
   222		ctx->copy_props = GF_FALSE;
   223		//copy properties at init or reconfig
   224		gf_filter_pid_copy_properties(ctx->opid, ctx->ipid);
   225		const GF_PropertyValue *p = gf_filter_pid_get_property(ctx->ipid, GF_PROP_PID_STREAM_TYPE);
   226		if (!p || (p->value.uint==GF_STREAM_FILE)) {
   227			gf_filter_pid_set_property(ctx->opid, GF_PROP_PID_STREAM_TYPE, &PROP_UINT(GF_STREAM_AUDIO));
   228		}
   229		gf_filter_pid_set_property(ctx->opid, GF_PROP_PID_SAMPLES_PER_FRAME, & PROP_UINT(AC3_FRAME_SIZE) );
   230		gf_filter_pid_set_property(ctx->opid, GF_PROP_PID_UNFRAMED, & PROP_BOOL(GF_FALSE) );
   231	
   232		if (ctx->duration.num)
   233			gf_filter_pid_set_property(ctx->opid, GF_PROP_PID_DURATION, & PROP_FRAC64(ctx->duration));
   234		if (!ctx->timescale && !gf_sys_is_test_mode())
   235			gf_filter_pid_set_property(ctx->opid, GF_PROP_PID_CAN_DATAREF, & PROP_BOOL(GF_TRUE ) );
   236	
   237	
   238		ctx->nb_ch = ctx->hdr.streams[0].channels;
   239		if (!ctx->timescale) {
   240			//we change sample rate, change cts
   241			if (ctx->cts && (ctx->sample_rate != ctx->hdr.sample_rate)) {
   242				ctx->cts = gf_timestamp_rescale(ctx->cts, ctx->sample_rate, ctx->hdr.sample_rate);
   243			}
   244		}
   245		ctx->sample_rate = ctx->hdr.sample_rate;
   246	
   247		gf_filter_pid_set_property(ctx->opid, GF_PROP_PID_TIMESCALE, & PROP_UINT(ctx->timescale ? ctx->timescale : ctx->sample_rate));
   248		gf_filter_pid_set_property(ctx->opid, GF_PROP_PID_SAMPLE_RATE, & PROP_UINT(ctx->sample_rate));
   249		gf_filter_pid_set_property(ctx->opid, GF_PROP_PID_NUM_CHANNELS, & PROP_UINT(ctx->nb_ch) );
   250	
   251		gf_filter_pid_set_property(ctx->opid, GF_PROP_PID_CODECID, & PROP_UINT(ctx->is_eac3 ? GF_CODECID_EAC3 : GF_CODECID_AC3) );
   252	
   253		ctx->hdr.is_ec3 = ctx->is_eac3;
   254		gf_odf_ac3_cfg_write(&ctx->hdr, &data, &size);
   255		gf_filter_pid_set_property(ctx->opid, GF_PROP_PID_DECODER_CONFIG, & PROP_DATA_NO_COPY(data, size) );
   256	
   257		if (ctx->bitrate) {
   258			gf_filter_pid_set_property(ctx->opid, GF_PROP_PID_BITRATE, & PROP_UINT(ctx->bitrate));
   259		}
   260	
   261		if (ctx->is_file && ctx->index) {
   262			gf_filter_pid_set_property(ctx->opid, GF_PROP_PID_PLAYBACK_MODE, & PROP_UINT(GF_PLAYBACK_MODE_FASTFORWARD) );
   263		}
   264	}
   265	
   266	static Bool ac3dmx_process_event(GF_Filter *filter, const GF_FilterEvent *evt)
   267	{
   268		u32 i;
   269		GF_FilterEvent fevt;
   270		GF_AC3DmxCtx *ctx = gf_filter_get_udta(filter);
   271	
   272		switch (evt->base.type) {
   273		case GF_FEVT_PLAY:
   274			if (!ctx->is_playing) {
   275				ctx->is_playing = GF_TRUE;
   276				ctx->cts = 0;
   277			}
   278			if (! ctx->is_file) {
   279				return GF_FALSE;
   280			}
   281			ctx->start_range = evt->play.start_range;
   282			ctx->in_seek = GF_TRUE;
   283			ctx->file_pos = 0;
   284			if (ctx->start_range) {
   285				for (i=1; i<ctx->index_size; i++) {
   286					if (ctx->indexes[i].duration>ctx->start_range) {
   287						ctx->cts = (u64) (ctx->indexes[i-1].duration * ctx->sample_rate);
   288						ctx->file_pos = ctx->indexes[i-1].pos;
   289						break;
   290					}
   291				}
   292			}
   293			if (!ctx->initial_play_done) {
   294				ctx->initial_play_done = GF_TRUE;
   295				//seek will not change the current source state, don't send a seek
   296				if (!ctx->file_pos)
   297					return GF_TRUE;
   298			}
   299			ctx->ac3_buffer_size = 0;
   300			ctx->resume_from = 0;
   301			//post a seek
   302			GF_FEVT_INIT(fevt, GF_FEVT_SOURCE_SEEK, ctx->ipid);
   303			fevt.seek.start_offset = ctx->file_pos;
   304			gf_filter_pid_send_event(ctx->ipid, &fevt);
   305	
   306			//cancel event
   307			return GF_TRUE;
   308	
   309		case GF_FEVT_STOP:
   310			//don't cancel event
   311			ctx->is_playing = GF_FALSE;
   312			ctx->cts = 0;
   313			return GF_FALSE;
   314	
   315		case GF_FEVT_SET_SPEED:
   316			//cancel event
   317			return GF_TRUE;
   318		default:
   319			break;
   320		}
   321		//by default don't cancel event - to rework once we have downloading in place
   322		return GF_FALSE;
   323	}
   324	
   325	static GFINLINE void ac3dmx_update_cts(GF_AC3DmxCtx *ctx)
   326	{
   327		if (ctx->timescale) {
   328			u64 inc = AC3_FRAME_SIZE;
   329			inc *= ctx->timescale;
   330			inc /= ctx->sample_rate;
   331			ctx->cts += inc;
   332		} else {
   333			ctx->cts += AC3_FRAME_SIZE;
   334		}
   335	}
   336	
   337	GF_Err ac3dmx_process(GF_Filter *filter)
   338	{
   339		GF_AC3DmxCtx *ctx = gf_filter_get_udta(filter);
   340		GF_FilterPacket *pck, *dst_pck;
   341		u8 *output;
   342		u8 *start;
   343		u32 pck_size, remain, prev_pck_size;
   344		u64 cts;
   345	
   346	restart:
   347		cts = GF_FILTER_NO_TS;
   348	
   349		//always reparse duration
   350		if (!ctx->duration.num)
   351			ac3dmx_check_dur(filter, ctx);
   352	
   353		if (ctx->opid && !ctx->is_playing)
   354			return GF_OK;
   355	
   356		pck = gf_filter_pid_get_packet(ctx->ipid);
   357		if (!pck) {
   358			if (gf_filter_pid_is_eos(ctx->ipid)) {
   359				if (!ctx->ac3_buffer_size) {
   360					if (ctx->opid)
   361						gf_filter_pid_set_eos(ctx->opid);
   362					if (ctx->src_pck) gf_filter_pck_unref(ctx->src_pck);
   363					ctx->src_pck = NULL;
   364					return GF_EOS;
   365				}
   366			} else {
   367				return GF_OK;
   368			}
   369		}
   370	
   371		prev_pck_size = ctx->ac3_buffer_size;
   372		if (pck && !ctx->resume_from) {
   373			const u8 *data = gf_filter_pck_get_data(pck, &pck_size);
   374			if (!pck_size) {
   375				gf_filter_pid_drop_packet(ctx->ipid);
   376				return GF_OK;
   377			}
   378	
   379			//max EAC3 frame is 4096 but we can have side streams, AC3 is 3840 - if we store more than 2 frames consider we have garbage
   380			if (ctx->ac3_buffer_size>100000) {
   381				GF_LOG(GF_LOG_WARNING, GF_LOG_MEDIA, ("[AC3Dmx] Trashing %d garbage bytes\n", ctx->ac3_buffer_size));
   382				ctx->ac3_buffer_size = 0;
   383			}
   384	
   385			if (ctx->byte_offset != GF_FILTER_NO_BO) {
   386				u64 byte_offset = gf_filter_pck_get_byte_offset(pck);
   387				if (!ctx->ac3_buffer_size) {
   388					ctx->byte_offset = byte_offset;
   389				} else if (ctx->byte_offset + ctx->ac3_buffer_size != byte_offset) {
   390					ctx->byte_offset = GF_FILTER_NO_BO;
   391					if ((byte_offset != GF_FILTER_NO_BO) && (byte_offset>ctx->ac3_buffer_size) ) {
   392						ctx->byte_offset = byte_offset - ctx->ac3_buffer_size;
   393					}
   394				}
   395			}
   396	
   397			if (ctx->ac3_buffer_size + pck_size > ctx->ac3_buffer_alloc) {
   398				ctx->ac3_buffer_alloc = ctx->ac3_buffer_size + pck_size;
   399				ctx->ac3_buffer = gf_realloc(ctx->ac3_buffer, ctx->ac3_buffer_alloc);
   400			}
   401			memcpy(ctx->ac3_buffer + ctx->ac3_buffer_size, data, pck_size);
   402			ctx->ac3_buffer_size += pck_size;
   403		}
   404	
   405		//input pid sets some timescale - we flushed pending data , update cts
   406		if (ctx->timescale && pck) {
   407			cts = gf_filter_pck_get_cts(pck);
   408			//init cts at first packet
   409			if (!ctx->cts && (cts != GF_FILTER_NO_TS))
   410				ctx->cts = cts;
   411		}
   412	
   413		if (cts == GF_FILTER_NO_TS) {
   414			//avoids updating cts
   415			prev_pck_size = 0;
   416		}
   417	
   418		remain = ctx->ac3_buffer_size;
   419		start = ctx->ac3_buffer;
   420	
   421		if (ctx->resume_from) {
   422			start += ctx->resume_from - 1;
   423			remain -= ctx->resume_from - 1;
   424			ctx->resume_from = 0;
   425		}
   426	
   427		if (!ctx->bs) {
   428			ctx->bs = gf_bs_new(start, remain, GF_BITSTREAM_READ);
   429		} else {
   430			gf_bs_reassign_buffer(ctx->bs, start, remain);
   431		}
   432		while (remain) {
   433			u8 *sync;
   434			Bool res;
   435			u32 sync_pos, bytes_to_drop=0;
   436	
   437			res = ctx->ac3_parser_bs(ctx->bs, &ctx->hdr, GF_TRUE);
   438	
   439			sync_pos = (u32) gf_bs_get_position(ctx->bs);
   440	
   441			//if not end of stream or no valid frame
   442			if (pck || !ctx->hdr.framesize) {
   443				//startcode not found or not enough bytes, gather more
   444				if (!res || (remain < sync_pos + ctx->hdr.framesize)) {
   445					if (sync_pos && ctx->hdr.framesize) {
   446						start += sync_pos;
   447						remain -= sync_pos;
   448					}
   449					break;
   450				}
   451				ac3dmx_check_pid(filter, ctx);
   452			}
   453			//may happen with very-short streams
   454			if (!ctx->sample_rate)
   455				ac3dmx_check_pid(filter, ctx);
   456	
   457			if (!ctx->is_playing) {
   458				ctx->resume_from = 1 + ctx->ac3_buffer_size - remain;
   459				return GF_OK;
   460			}
   461	
   462			if (sync_pos) {
   463				GF_LOG(GF_LOG_WARNING, GF_LOG_MEDIA, ("[AC3Dmx] %d bytes unrecovered before sync word\n", sync_pos));
   464			}
   465			sync = start + sync_pos;
   466	
   467			if (ctx->in_seek) {
   468				u64 nb_samples_at_seek = (u64) (ctx->start_range * ctx->hdr.sample_rate);
   469				if (ctx->cts + AC3_FRAME_SIZE >= nb_samples_at_seek) {
   470					//u32 samples_to_discard = (ctx->cts + ctx->dts_inc) - nb_samples_at_seek;
   471					ctx->in_seek = GF_FALSE;
   472				}
   473			}
   474	
   475			bytes_to_drop = sync_pos + ctx->hdr.framesize;
   476			if (ctx->timescale && !prev_pck_size &&  (cts != GF_FILTER_NO_TS) ) {
   477				//trust input CTS if diff is more than one sec
   478				if ((cts > ctx->cts + ctx->timescale) || (ctx->cts > cts + ctx->timescale))
   479					ctx->cts = cts;
   480				cts = GF_FILTER_NO_TS;
   481			}
   482	
   483			if (!ctx->in_seek && remain >= ctx->hdr.framesize) {
   484				dst_pck = gf_filter_pck_new_alloc(ctx->opid, ctx->hdr.framesize, &output);
   485				if (!dst_pck) return GF_OUT_OF_MEM;
   486	
   487				if (ctx->src_pck) gf_filter_pck_merge_properties(ctx->src_pck, dst_pck);
   488	
   489				memcpy(output, sync, ctx->hdr.framesize);
   490				gf_filter_pck_set_dts(dst_pck, ctx->cts);
   491				gf_filter_pck_set_cts(dst_pck, ctx->cts);
   492				if (ctx->timescale && (ctx->timescale!=ctx->sample_rate))
   493					gf_filter_pck_set_duration(dst_pck, (u32) gf_timestamp_rescale(AC3_FRAME_SIZE, ctx->sample_rate, ctx->timescale));
   494				else
   495					gf_filter_pck_set_duration(dst_pck, AC3_FRAME_SIZE);
   496				gf_filter_pck_set_sap(dst_pck, GF_FILTER_SAP_1);
   497				gf_filter_pck_set_framing(dst_pck, GF_TRUE, GF_TRUE);
   498	
   499				if (ctx->byte_offset != GF_FILTER_NO_BO) {
   500					gf_filter_pck_set_byte_offset(dst_pck, ctx->byte_offset + ctx->hdr.framesize);
   501				}
